class.description:
[CgameLagCompensation] keeps a short position history for every character so the server can judge a swing or shot against where the target was on the attacker's screen: half the round trip plus the client's interpolation delay ago. The rewind is capped, so high-ping players cannot hit around corners.
[codeblock]
history.record(target_id, now, target.position)
var rewind := CgameLagCompensation.rewind_for(attacker_round_trip)
var where := history.position_at(target_id, now - rewind, target.position)
[/codeblock]
